app = Flask(__name__)


@app.route('/')
def redirect_to_next_url():
    '''
    Redirect the user to the next_url specified on the GET request.
    '''
    next_url = request.args.get('next_url', '/default')
    return redirect(next_url)

if __name__ == '__main__':
    app.run(debug=True)"
